-- 原宣战报名独立事实；不生成比赛结果或奖励。
CREATE TABLE IF NOT EXISTS p13_union_fight_fighters (guild_id VARCHAR(64) NOT NULL,day VARCHAR(10) NOT NULL,player_id BIGINT NOT NULL,role INT NOT NULL,applied_at BIGINT NOT NULL DEFAULT 0,first_on BOOLEAN NOT NULL DEFAULT FALSE,auto_fight BOOLEAN NOT NULL DEFAULT FALSE,name VARCHAR(128) NOT NULL,fight_power BIGINT NOT NULL DEFAULT 0,battle LONGBLOB,snapshot_hash CHAR(64) NOT NULL DEFAULT '',updated_at BIGINT NOT NULL DEFAULT 0,battle_adjust_times INT NOT NULL DEFAULT 0,default_items VARCHAR(512) NOT NULL DEFAULT '',PRIMARY KEY(guild_id,day,player_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
